head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > loadPageCommon]<br/>페이지 단위의 공통 컴포넌트(pageCommon)를 비동기로 로드하여 현재 WFrame 에 적용합니다.<br/>",
    "validation" : [
        "페이지 단위의 공통 컴포넌트(pageCommon)를 비동기로 로드하여 현재 WFrame 에 적용할 수 있어야 합니다.",
        "infoArray(필수) 파라미터로 로드할 페이지 공통 정보 객체가 담긴 배열을 설정할 수 있어야 합니다.",
        "infoArray(필수) 파라미터가 Array 가 아니면 pageCommon 이 로드되지 않아야 합니다.",
        "infoArray[i].src(필수) 파라미터로 로드할 공통 컴포넌트(pageCommon) 의 XML 파일 경로를 설정할 수 있어야 합니다.",
        "infoArray[i].id(필수) 파라미터로 공통 컴포넌트(pageCommon) 의 식별자를 설정할 수 있어야 합니다.",
        "모든 공통 컴포넌트(pageCommon) 의 로드 완료를 나타내는 Promise 객체를 반환해야 합니다.",
        "반환된 Promise 는 await 또는 .then() 으로 로드 완료 후 처리를 할 수 있어야 합니다."
    ]
}



scwin.PAGE_COMMON_PATHS = {
    "pc1" : "/sample/common_link/$p_loadPageCommon_pc1.xml",
    "pc2" : "/sample/common_link/$p_loadPageCommon_pc2.xml"
};

// 테스트 시작 전 특정 이름의 WFrame scope 슬롯을 초기화
scwin.resetSlot = function (slotName) {
    try {
        var frameObj = $p.getFrame();
        if (frameObj && frameObj.scope && frameObj.scope[slotName]) {
            delete frameObj.scope[slotName];
        }
    } catch (e) {}
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// case1 : 배열 + await → common1, common2 로드 후 메소드 호출 확인 (pageCommon 2개 동시 로드)
scwin.btn_loadPageCommon_await_onclick = async function () {
    scwin.resetSlot("common1");
    scwin.resetSlot("common2");

    var infoArr = [
        {"src" : scwin.PAGE_COMMON_PATHS.pc1, "id" : "common1"},
        {"src" : scwin.PAGE_COMMON_PATHS.pc2, "id" : "common2"}
    ];
    await $p.loadPageCommon(infoArr);

    wf_body_bottom.getObj("scwin").setReturnValue("common1.getName() : " + common1.getName());
    wf_body_bottom.getObj("scwin").setReturnValue("common2.sum(1, 2) : " + common2.sum(1, 2));
}



// case2 : .then() 후속 처리 + Promise 반환 확인
scwin.btn_loadPageCommon_then_onclick = function () {
    scwin.resetSlot("common3");

    var infoArr = [{"src" : scwin.PAGE_COMMON_PATHS.pc1, "id" : "common3"}];
    var retVal = $p.loadPageCommon(infoArr);

    wf_body_bottom.getObj("scwin").setReturnValue("retVal instanceof Promise : " + (retVal instanceof Promise));

    retVal.then(function () {
        wf_body_bottom.getObj("scwin").setReturnValue(".then() 후 common3.greet('Square') : '" + common3.greet("Square") + "'");
    });
}



// case3 : infoArray 가 Array 가 아닌 경우 (String 전달) → pageCommon 미로드
scwin.btn_loadPageCommon_notArray_onclick = async function () {
    scwin.resetSlot("common_notArray");

    await $p.loadPageCommon("not_an_array");

    var frameObj = $p.getFrame();
    wf_body_bottom.getObj("scwin").setReturnValue("infoArray 가 Array 가 아닐 때 scope.common_notArray : " + (typeof frameObj.scope.common_notArray));
}



// par_case selectbox 값에 따라 각 테스트 케이스 실행
scwin.btn_loadPageCommon_run_onclick = function () {
    var caseId = par_case.getValue();
    var handlers = {
        "await"    : scwin.btn_loadPageCommon_await_onclick,
        "then"     : scwin.btn_loadPageCommon_then_onclick,
        "notArray" : scwin.btn_loadPageCommon_notArray_onclick
    };
    var fn = handlers[caseId];
    if (typeof fn === "function") {
        fn();
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("케이스를 선택하세요.");
    }
}
